// A code block, highlighted on the SERVER. Shiki is the highlighter VS Code uses, so
// the grammars and themes are the ones the reader already knows, and running it at
// build time means the page ships the markup and none of the highlighter: only the
// copy control is client code.
//
// Two themes are baked into one render (`--shiki-light` / `--shiki-dark` on every
// token) and code.css picks with the theme, so switching does not re-highlight and
// cannot flash.

import {
  transformerNotationDiff,
  transformerNotationErrorLevel,
  transformerNotationFocus,
  transformerNotationHighlight,
  transformerNotationWordHighlight,
} from "@shikijs/transformers"
import { type BundledLanguage, codeToHtml } from "shiki"
import { Copy } from "@/registry/base-nova/ui/copy"
import "./code.css"

export interface CodeProps {
  /** The source. Common leading indentation is removed, so a snippet can be written
   *  indented inside the code that renders it and still read flush. */
  children: string
  /** A Shiki language id. `text` when it is not code, which skips the grammar. */
  lang?: BundledLanguage | "text"
  /** A path or a name for the tab. Without one the frame is bare. */
  filename?: string
  /** Hide the copy control, for a snippet nobody would want in their clipboard. */
  copy?: boolean
  /** Lines to mark, `"2"` or `"1,4-6"`, counted from 1. For source you do NOT own:
   *  a file rendered verbatim cannot carry `[!code highlight]` comments without them
   *  becoming part of the file. Where you do own it, prefer the comments, which move
   *  with the lines when the code is edited. */
  highlight?: string
  /** Number the lines. Off by default: most snippets are short enough that numbers
   *  are furniture, and they are only worth their width when something refers to one. */
  lines?: boolean
  /** Read `[!code ...]` comments. ON, except where the source is being shown AS
   *  ITSELF: a file that writes those comments inside a string would have them eaten
   *  out of its own listing, and a block promising verbatim would be quietly lying. */
  notations?: boolean
  className?: string
}

/** `"1,4-6"` to the set {1,4,5,6}. Screams rather than silently marking nothing. */
export function parseLines(spec: string): Set<number> {
  const out = new Set<number>()
  for (const part of spec.split(",")) {
    const range = part.trim()
    if (!range) continue
    const [a, b = a] = range.split("-").map((n) => Number(n.trim()))
    if (!Number.isInteger(a) || !Number.isInteger(b) || a === undefined)
      throw new Error(`code: "${range}" is not a line or a range of lines`)
    for (let n = a; n <= (b as number); n++) out.add(n)
  }
  return out
}

/** Strip the shortest indentation any non-blank line has, and the blank first and
 *  last lines a template literal always brings. */
export function dedent(src: string): string {
  const lines = src.replace(/\t/g, "  ").split("\n")
  while (lines.length && !lines[0]?.trim()) lines.shift()
  while (lines.length && !lines[lines.length - 1]?.trim()) lines.pop()
  const pad = Math.min(
    ...lines
      .filter((l) => l.trim())
      .map((l) => l.length - l.trimStart().length),
  )
  return lines.map((l) => l.slice(pad)).join("\n")
}

export async function Code({
  children,
  lang = "tsx",
  filename,
  copy = true,
  highlight,
  lines,
  notations = true,
  className,
}: CodeProps) {
  const source = dedent(children)
  const marked = highlight ? parseLines(highlight) : null
  const html = await codeToHtml(source, {
    lang,
    themes: { light: "github-light", dark: "github-dark" },
    defaultColor: false,
    transformers: [
      // The notations travel INSIDE the source, so they survive an edit that moves a
      // line and they are what a reader copies out of a doc. Shiki strips the comment
      // from the rendered output; the clipboard gets `source`, which still has it.
      ...(notations
        ? [
            transformerNotationDiff({ matchAlgorithm: "v3" }),
            transformerNotationHighlight({ matchAlgorithm: "v3" }),
            transformerNotationWordHighlight({ matchAlgorithm: "v3" }),
            transformerNotationFocus({ matchAlgorithm: "v3" }),
            transformerNotationErrorLevel({ matchAlgorithm: "v3" }),
          ]
        : []),
      // ...and the `highlight` prop for source nobody may write into.
      {
        name: "ag:highlight-prop",
        line(node, line) {
          if (marked?.has(line)) this.addClassToHast(node, "highlighted")
        },
      },
    ],
  })
  return (
    <div
      className={`ag-code${lines ? " ag-code-numbered" : ""}${className ? ` ${className}` : ""}`}
    >
      <div className="ag-code-bar">
        <span className="ag-code-name">{filename ?? lang}</span>
        {copy && <Copy value={source} label />}
      </div>
      {/* Shiki's own <pre><code>, styled by code.css. */}
      <div
        className="ag-code-scroll"
        // biome-ignore lint/security/noDangerouslySetInnerHtml: shiki's own output, built on the server from a string prop, never from anything a reader can reach
        dangerouslySetInnerHTML={{ __html: html }}
      />
    </div>
  )
}

/* The frame around highlighted code. Shiki writes both themes onto every token as
   custom properties; this picks one, so a theme switch is a repaint and never a
   re-highlight, and there is no flash of the wrong palette on first paint. */

.ag-code {
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  background: var(--sidebar);
}
.ag-code-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.375rem 0.5rem 0.375rem 0.875rem;
  border-bottom: 1px solid var(--border);
}
.ag-code-name {
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 0.75rem;
  color: var(--muted-foreground);
  user-select: none;
}
/* The scroller, not the <pre>: the frame keeps its corners while long lines run. */
.ag-code-scroll {
  overflow-x: auto;
}
/* Shiki with `defaultColor: false` writes its palette as custom properties and sets
   no colour of its own, so the frame keeps its own surface with nothing to override. */
.ag-code pre {
  margin: 0;
  padding: 1rem 0.875rem;
  background: transparent;
  font-size: 0.8125rem;
  line-height: 1.65;
  tab-size: 2;
}
.ag-code code {
  display: block;
  width: fit-content;
  min-width: 100%;
  font-family: var(--font-mono, ui-monospace, monospace);
}

/* Shiki with `defaultColor: false` writes --shiki-light and --shiki-dark and no
   colour of its own, so the theme chooses here. */
.ag-code span {
  color: var(--shiki-light);
}
.dark .ag-code span {
  color: var(--shiki-dark);
}

/* Reading a long snippet should not mean reading a scrollbar. */
.ag-code-scroll {
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklab, var(--foreground) 20%, transparent)
    transparent;
}

/* ---- marked lines.

   A marked line is marked EDGE TO EDGE, which is why `.line` is a block that runs the
   full scroll width: a tint that stops at the end of the text draws a ragged shape
   down the block and reads as damage rather than emphasis. The gutter bar is what
   survives being scrolled sideways, when the tint under a long line is off screen. */
.ag-code .line {
  display: inline-block;
  width: 100%;
  padding-inline: 0.875rem;
  margin-inline: -0.875rem;
  border-left: 2px solid transparent;
}
.ag-code .line.highlighted {
  background: color-mix(
    in oklab,
    var(--brand, var(--foreground)) 10%,
    transparent
  );
  border-left-color: color-mix(
    in oklab,
    var(--brand, var(--foreground)) 55%,
    transparent
  );
}
/* An error or a warning is a highlight that has something to say, so it keeps the
   shape and changes only the hue. */
.ag-code .line.highlighted.error {
  background: color-mix(in oklab, var(--tone-bad) 12%, transparent);
  border-left-color: var(--tone-bad);
}
.ag-code .line.highlighted.warning {
  background: color-mix(in oklab, var(--tone-warn) 12%, transparent);
  border-left-color: var(--tone-warn);
}

/* ---- a diff.

   The sign is a real character in the gutter, not a colour: colour alone is invisible
   to a reader who cannot separate red from green, and it does not survive a
   screenshot pasted into a grey chat. */
.ag-code .line.diff {
  position: relative;
}
.ag-code .line.diff::before {
  position: absolute;
  left: 0.25rem;
  opacity: 0.7;
}
.ag-code .line.diff.add {
  background: color-mix(in oklab, var(--tone-ok) 14%, transparent);
  border-left-color: var(--tone-ok);
}
.ag-code .line.diff.add::before {
  content: "+";
  color: var(--tone-ok);
}
.ag-code .line.diff.remove {
  background: color-mix(in oklab, var(--tone-bad) 12%, transparent);
  border-left-color: var(--tone-bad);
}
/* Removed code is still readable, just plainly on its way out. */
.ag-code .line.diff.remove {
  opacity: 0.65;
}
.ag-code .line.diff.remove::before {
  content: "-";
  color: var(--tone-bad);
}

/* ---- focus: everything else steps back, and comes back on hover, because a reader
   who wants the surrounding lines should not have to leave the page to see them. */
.ag-code:has(.focused) .line:not(.focused) {
  filter: blur(2px);
  opacity: 0.5;
  transition:
    filter 200ms ease,
    opacity 200ms ease;
}
.ag-code:has(.focused):hover .line:not(.focused) {
  filter: none;
  opacity: 1;
}

/* ---- a word, marked inside the line. */
.ag-code .highlighted-word {
  border-radius: 0.25rem;
  padding: 0.1em 0.25em;
  background: color-mix(
    in oklab,
    var(--brand, var(--foreground)) 14%,
    transparent
  );
  box-shadow: 0 0 0 1px
    color-mix(in oklab, var(--brand, var(--foreground)) 30%, transparent);
}

/* ---- line numbers, opt-in. A counter, so nothing is added to the copied text. */
.ag-code-numbered code {
  counter-reset: ag-line;
}
.ag-code-numbered .line {
  counter-increment: ag-line;
  padding-left: 3rem;
}
.ag-code-numbered .line::after {
  content: counter(ag-line);
  position: absolute;
  left: 0;
  width: 2.25rem;
  text-align: right;
  color: var(--muted-foreground);
  opacity: 0.5;
  user-select: none;
}
.ag-code-numbered .line {
  position: relative;
}
.ag-code-numbered .line.diff::before {
  left: 2.5rem;
}

@media (prefers-reduced-motion: reduce) {
  .ag-code:has(.focused) .line:not(.focused) {
    transition: none;
  }
}
